type AccessibilityStatus = "open" | "authentication";
type AccessibilityPoint = { kind: "web" | "download"; label: string; display: string; host: string; status?: AccessibilityStatus; href?: string; knowledgeObjectId?: string };
function accessibilityLinks(id: ObjectId, drafts: Drafts): AccessibilityPoint[] {
  const content = workingFileValue(id, "access.metadata.txt", drafts);
  const graph = buildCanonicalRdfGraph(content);
  const accessPredicates = new Set(["https://schema.org/url", "https://schema.org/urlTemplate", "https://schema.org/distribution", "https://schema.org/contentUrl", "https://schema.org/downloadUrl"]);
  const points: AccessibilityPoint[] = [];
  const accessStatus = (conditions: string): AccessibilityStatus | undefined => /(?:no authentication|public access|open access|\bnone\b)/i.test(conditions) ? "open" : /(?:authentication|password)[^.]{0,48}required|required[^.]{0,48}(?:authentication|password)/i.test(conditions) ? "authentication" : undefined;
  const legacyConditions = graph.statements.filter((statement) => statement.predicate.value === "https://schema.org/additionalProperty" && statement.object.termType === "BlankNode").flatMap((statement) => {
    const members = graph.statements.filter((candidate) => candidate.subject.id === statement.object.id), name = members.find((candidate) => candidate.predicate.value === "https://schema.org/name")?.object.value ?? "";
    return /access (?:conditions|mode)/i.test(name) ? members.filter((candidate) => candidate.predicate.value === "https://schema.org/value").map((candidate) => candidate.object.value) : [];
  }).join("; ");
  const addWebPoint = (candidate: string, label = "Open through HTTPS", description = candidate, conditions = legacyConditions) => {
    const cleaned = candidate.replace(/[),.;!?]+$/, "");
    const href = /^www\./i.test(cleaned) ? `https://${cleaned}` : cleaned;
    try {
      const parsed = new URL(href);
      if (["http:", "https:"].includes(parsed.protocol) && !points.some((point) => point.href === parsed.href)) points.push({ kind: "web", href: parsed.href, display: description, host: parsed.hostname, label, status: accessStatus(conditions) });
    } catch {}
  };
  graph.statements.filter((statement) => statement.predicate.value === "https://schema.org/potentialAction" && statement.object.termType === "BlankNode").forEach((actionStatement) => {
    const actionMembers = graph.statements.filter((statement) => statement.subject.id === actionStatement.object.id);
    const actionName = actionMembers.find((statement) => statement.predicate.value === "https://schema.org/name")?.object.value ?? "Access knowledge object";
    const target = actionMembers.find((statement) => statement.predicate.value === "https://schema.org/target" && statement.object.termType === "BlankNode")?.object;
    if (!target) return;
    const targetMembers = graph.statements.filter((statement) => statement.subject.id === target.id);
    const route = targetMembers.find((statement) => accessPredicates.has(statement.predicate.value))?.object.value;
    const description = targetMembers.find((statement) => statement.predicate.value === "https://schema.org/description")?.object.value ?? route ?? actionName;
    const protocol = targetMembers.find((statement) => statement.predicate.value === "https://schema.org/name")?.object.value ?? "";
    const identifier = targetMembers.find((statement) => statement.predicate.value === "https://schema.org/identifier")?.object.value;
    if (route) addWebPoint(route, actionName, description, description);
    else if (identifier && protocol === "FDO Bench KO Access API 1.0") points.push({ kind: "download", knowledgeObjectId: identifier, label: actionName === "Download from FDO Bench" ? "Download from Bench" : actionName, host: protocol, display: description, status: accessStatus(description) });
  });
  graph.statements.filter((statement) => accessPredicates.has(statement.predicate.value) && /^(?:https?:\/\/|www\.)/i.test(statement.object.value)).forEach((statement) => addWebPoint(statement.object.value));
  return points;
}

