  const typeMap = useMemo(() => { const map = new Map<string, CanonicalRdfTerm[]>(); graph.statements.filter((statement) => statement.predicate.value === RDF_TYPE).forEach((statement) => map.set(statement.subject.id, [...(map.get(statement.subject.id) ?? []), statement.object])); return map; }, [graph]);
