  useEffect(() => { requestAnimationFrame(fitGraph); }, [focusTerm?.id, visible.length]);
  const chooseEdge = (statement: CanonicalRdfStatement) => { setSelection({ kind: "edge", statement }); window.dispatchEvent(new CustomEvent("rdf-statement-select", { detail: { statementId: statement.id } })); };
  const counts = (term: CanonicalRdfTerm) => ({ incoming: relationships.filter((statement) => statement.object.id === term.id).length, outgoing: relationships.filter((statement) => statement.subject.id === term.id).length });
  if (!focusTerm) return <div className="relationshipEmpty">No RDF relationships were found.</div>;
