    <div className="relationshipToolbar" aria-label="Relationship display controls">
      <label>Depth<select value={depth} onChange={(event) => setDepth(event.target.value)}><option value="1">1</option><option value="2">2</option><option value="all">All</option></select></label>
      <button type="button" className="relationshipInspectorToggle" aria-expanded={inspectorOpen} aria-controls="relationship-evidence-inspector" onClick={() => setInspectorOpen((open) => !open)}>{inspectorOpen ? "Close inspector" : "Open inspector"}</button>
    </div>
