function KnowledgeObjectShade({ objectId, drafts }: { objectId: ObjectId; drafts: Drafts }) {
  const [graphicView, setGraphicView] = useState<"overview" | "logic" | "files" | "runner" | null>(null);
  const [specsOpen, setSpecsOpen] = useState(false);
  const runner = runnerAvailabilityByObject[objectId];
  const graphicAbstract = graphicAbstractFile(filesForObject(objectId));
  const graphicLogic = graphicLogicFile(filesForObject(objectId));
  const abstractSource = graphicAbstract ? `data:${graphicAbstractMimeType(graphicAbstract)};base64,${objectBinaryOverrides[draftKey(objectId, graphicAbstract)]}` : "";
  const logicSource = graphicLogic ? `data:${graphicAbstractMimeType(graphicLogic)};base64,${objectBinaryOverrides[draftKey(objectId, graphicLogic)]}` : "";
  const purpose = knowledgeObjectPurpose(objectId, drafts);
  const fullCksFile = fullCksDocumentFile(filesForObject(objectId));
  const fullCksProjection = fullCksFile ? documentProjectionFor(objectId, fullCksFile) : undefined;
  const notebooks = knowledgeObjectNotebooks(objectId, drafts);
  const summaryFacts = [
    ["Information Page", "A fully metadata-driven overview"],
    ["Size", formatKnowledgeObjectSize(knowledgeObjectByteSize(objectId))],
    ["Knowledge Elements", knowledgeElementCount(objectId, drafts)],
    ["Method", knowledgeObjectMethod(objectId, drafts)],
    ["Interactive Notebooks", String(notebooks.length)],
  ];
  return <><details className="koObjectShade">
    <summary><strong>{objectName(objectId)}</strong>{graphicAbstract && <button type="button" className="koShadeGraphic" onClick={(event) => { event.preventDefault(); event.stopPropagation(); setGraphicView("overview"); }} aria-label={`Open ${objectName(objectId)} overview`}>Overview</button>}{graphicLogic && <button type="button" className="koShadeGraphic" onClick={(event) => { event.preventDefault(); event.stopPropagation(); setGraphicView("logic"); }} aria-label={`Open ${objectName(objectId)} logic`}>Logic</button>}<button type="button" className="koShadeGraphic koShadeRun" disabled={!runner?.available} title={runner?.available ? "Run this knowledge object's declared browser operation" : runner?.validationError ?? "No browser Runner is supplied by this knowledge object."} onClick={(event) => { event.preventDefault(); event.stopPropagation(); if (runner?.available) setGraphicView("runner"); }} aria-label={runner?.available ? `Run ${objectName(objectId)}` : `${objectName(objectId)} Runner unavailable`}>Run</button><button type="button" className="koShadeFileCount" onClick={(event) => { event.preventDefault(); event.stopPropagation(); setGraphicView("files"); }} aria-label={`Open ${objectName(objectId)} files`}>{filesForObject(objectId).length} Files</button></summary>
    <div className="facetList koSummaryFacetList">{summaryFacts.map(([label, value], index) => <div className="facetRow declared" key={label}><span className="facetNumber">{index + 1}</span><span className="facetCopy"><strong>{label}</strong>{value && <small>{value}</small>}</span>{label === "Information Page" && <button type="button" className="koSummarySpecsButton" onClick={() => openEmbeddedInformationPage(objectId)} aria-label={`Open ${objectName(objectId)} information page`}>Information</button>}{label === "Knowledge Elements" && fullCksProjection?.sanitizedHtml && <button type="button" className="koSummarySpecsButton" aria-label={`Open ${objectName(objectId)} full CKS specification`} onClick={() => setSpecsOpen(true)}>Specs</button>}{label === "Interactive Notebooks" && <span className="koNotebookActions">{notebooks.map((notebook) => notebook.href ? <a key={notebook.kind} className="koSummarySpecsButton" href={notebook.href} target="_blank" rel="noopener noreferrer" aria-label={`${notebook.kind === "Scribbler" ? "Launch" : "Open"} ${objectName(objectId)} ${notebook.kind} notebook`}>{notebook.kind}</a> : null)}</span>}</div>)}</div>
  </details>{specsOpen && fullCksProjection && createPortal(<DocumentProjectionDialog objectId={objectId} file={fullCksFile} projection={fullCksProjection} onClose={() => setSpecsOpen(false)} />, document.body)}{graphicView === "runner" && runner?.bundleSource && runner.manifest?.knowledgeObjectId ? createPortal(<KnowledgeObjectRunnerView objectId={objectId} bundleSource={runner.bundleSource} knowledgeObjectId={runner.manifest.knowledgeObjectId} onClose={() => setGraphicView(null)} />, document.body) : graphicView === "files" ? createPortal(<KnowledgeObjectFilesView objectId={objectId} drafts={drafts} onClose={() => setGraphicView(null)} />, document.body) : graphicView && graphicView !== "runner" && createPortal(<KnowledgeObjectGraphicView objectId={objectId} source={graphicView === "overview" ? abstractSource : logicSource} purpose={purpose} kind={graphicView} onClose={() => setGraphicView(null)} />, document.body)}</>;
}

function FindabilityGuidedEditor({ value, canonicalSource, state, onEdit }: { value: string; canonicalSource: string; state: ReturnType<typeof evaluateFindabilityEnrichment>; onEdit: (value: string) => void }) {
  const simulatedDescription = "This knowledge object uses a diabetic foot ulcer’s initial wound area and duration to place it into a published prognostic group and estimate its probability of healing within 16 weeks.";
  const simulatedSearchTerms = [
    "diabetic foot ulcer healing prognosis",
    "16-week wound healing probability",
    "baseline wound area and duration",
    "pretreatment DFU prognostic stratification",
    "Margolis two-factor prognostic model",
  ];
  const [transitioning, setTransitioning] = useState(false);
  const textValues = useMemo(() => getFindabilityTextValues(value), [value]);
  const [description, setDescription] = useState(textValues.description);
  const [searchTerms, setSearchTerms] = useState(textValues.searchTerms.join("\n"));
  const [sourceValue, setSourceValue] = useState(value);
  if (sourceValue !== value) {
    setSourceValue(value);
    setDescription(textValues.description);
    setSearchTerms(textValues.searchTerms.join("\n"));
  }
  const subjectOptions = useMemo(() => getFindabilitySubjectOptions(canonicalSource), [canonicalSource]);
  const selectedSubjects = useMemo(() => getSelectedFindabilitySubjects(value), [value]);
  const outputOptions = useMemo(() => getFindabilityOutputTermOptions(canonicalSource), [canonicalSource]);
  const selectedOutputs = useMemo(() => getSelectedFindabilityOutputTerms(value), [value]);
  const searchLines = searchTerms.split("\n");
  const firstThreeSearchLinesComplete = searchLines.slice(0, 3).length === 3 && searchLines.slice(0, 3).every((term) => term.trim().length > 0);
  const parsedTerms = (text = searchTerms) => text.split("\n").map((term) => term.trim()).filter(Boolean);
  const construct = (changes: Record<string, unknown>) => {
    const nextValue = constructFindabilityMetadata(canonicalSource, { ...getFindabilityEnrichmentInput(value), ...changes });
    if (getFindabilityUnlockState(nextValue).unlocked) {
      setTransitioning(true);
      window.setTimeout(() => onEdit(nextValue), window.matchMedia("(prefers-reduced-motion: reduce)").matches ? 120 : 1800);
      return;
    }
    onEdit(nextValue);
  };
  if (transitioning) return <section className="metadataCompletionTransition" role="status" aria-live="polite"><span>Metadata complete</span><strong>Preparing structured table</strong></section>;
  return <section className="findabilityEnrichmentGate findabilityGuidedEditor" aria-label="Findability guided editor">
    <header><span>Findability enrichment</span><h3>Make this Knowledge Object findable</h3></header>
    <div className="guidedEditorFields">
      <article className={state.fullName ? "complete guidedField guidedCheckboxField" : "missing guidedField guidedCheckboxField"}><div><strong>Full name</strong><small>Confirm the established name. It cannot be changed in this exercise.</small></div><label className="guidedCheckRow"><input type="checkbox" checked={state.fullName} onChange={(event) => construct({ fullNameConfirmed: event.target.checked })} /><span><b>{getCanonicalFindabilityName(canonicalSource)}</b><small>The fixed human-readable title used to identify this knowledge object.</small></span></label><span>{state.fullName ? "Confirmed" : "Needs confirmation"}</span></article>
      <article className={state.description ? "complete guidedField guidedTextField" : "missing guidedField guidedTextField"}><div className="guidedFieldHeading"><label htmlFor="findability-description"><strong>Description</strong><small>Enter more than 10 characters.</small></label><button type="button" onClick={() => { setDescription(simulatedDescription); construct({ description: simulatedDescription }); }}>Assist Me</button></div><textarea id="findability-description" value={description} onChange={(event) => { const next = event.target.value; setDescription(next); construct({ description: next }); }} rows={3} /><span>{description.trim().length > 10 ? "Complete" : "Needs more detail"}</span></article>
      <article className={state.controlledSubject ? "complete guidedField guidedCheckboxField" : "missing guidedField guidedCheckboxField"}><div><strong>Controlled subjects</strong><small>Select at least one standardized subject. Each checked term adds a vocabulary identifier, not merely display text.</small></div><div className="guidedCheckList">{subjectOptions.map((option) => <label className="guidedCheckRow" key={option.iri}><input type="checkbox" checked={selectedSubjects.includes(option.iri)} onChange={(event) => construct({ controlledSubjectIris: event.target.checked ? [...selectedSubjects, option.iri] : selectedSubjects.filter((iri) => iri !== option.iri) })} /><span><b>{option.label}</b><small>{option.description}</small><code>{option.iri.split("/").at(-1)}</code></span></label>)}</div><span>{selectedSubjects.length} selected · {state.controlledSubject ? "Complete" : "Needs work"}</span></article>
      <article className={state.searchTerms ? "complete guidedField guidedTextField" : "missing guidedField guidedTextField"}><div className="guidedFieldHeading"><label htmlFor="findability-keywords"><strong>Search terms</strong><small>Enter one search term on each of the first three lines.</small></label><button type="button" onClick={() => { const next = simulatedSearchTerms.join("\n"); setSearchTerms(next); construct({ searchTerms: simulatedSearchTerms }); }}>Assist Me</button></div><textarea id="findability-keywords" value={searchTerms} onChange={(event) => { const next = event.target.value; setSearchTerms(next); construct({ searchTerms: parsedTerms(next) }); }} rows={3} /><span>{firstThreeSearchLinesComplete ? "Complete" : `${searchLines.slice(0, 3).filter((term) => term.trim()).length} of 3 lines`}</span></article>
      <article className={state.outputVocabulary ? "complete guidedField guidedCheckboxField" : "missing guidedField guidedCheckboxField"}><div><strong>Prognostic grouping outputs</strong><small>Confirm all four result groupings defined by this knowledge object.</small></div><div className="guidedCheckList outputCheckList">{outputOptions.map((option) => <label className="guidedCheckRow" key={option.iri}><input type="checkbox" checked={selectedOutputs.includes(option.iri)} onChange={(event) => construct({ outputTermIris: event.target.checked ? [...selectedOutputs, option.iri] : selectedOutputs.filter((iri) => iri !== option.iri) })} /><span><b>{option.code} · {option.label}</b><small>{option.description}</small></span></label>)}</div><span>{selectedOutputs.length} of {outputOptions.length} confirmed · {state.outputVocabulary ? "Complete" : "Needs work"}</span></article>
    </div>
  </section>;
}

function ReusabilityGuidedEditor({ value, canonicalSource, metadataSource, state, onEdit }: { value: string; canonicalSource: string; metadataSource: string; state: ReturnType<typeof evaluateReusabilityEnrichment>; onEdit: (value: string) => void }) {
  const simulatedScope = "Intended for demonstration, education, and research involving one established diabetic foot ulcer at its first clinical assessment. Wound area and duration must describe the same ulcer and use supported units. The knowledge object assigns one of four published pretreatment prognostic groups and its associated probability of healing by 16 weeks. It does not diagnose or measure ulcers, calculate individualized continuous risk, consider factors beyond area and duration, evaluate treatments or HBOT eligibility, or recommend care. Use beyond the source populations and settings requires independent validation and clinical governance.";
  const [transitioning, setTransitioning] = useState(false);
  const currentScope = useMemo(() => getReusabilityScopeText(value), [value]);
  const [scope, setScope] = useState(currentScope);
  const [sourceValue, setSourceValue] = useState(value);
  if (sourceValue !== value) {
    setSourceValue(value);
    setScope(currentScope);
  }
  const licenseOptions = useMemo(() => getReusabilityLicenseOptions(canonicalSource), [canonicalSource]);
  const selectedLicenses = useMemo(() => getSelectedReusabilityLicenses(value), [value]);
  const evidenceOptions = useMemo(() => getReusabilityEvidencePresentationOptions(canonicalSource, metadataSource), [canonicalSource, metadataSource]);
  const selectedEvidence = useMemo(() => getSelectedReusabilityEvidence(value), [value]);
  const construct = (changes: Record<string, unknown>) => {
    const nextValue = constructReusabilityMetadata(canonicalSource, { ...getReusabilityEnrichmentInput(value), ...changes });
    if (getReusabilityUnlockState(nextValue).unlocked) {
      setTransitioning(true);
      window.setTimeout(() => onEdit(nextValue), window.matchMedia("(prefers-reduced-motion: reduce)").matches ? 120 : 1800);
      return;
    }
    onEdit(nextValue);
  };
  if (transitioning) return <section className="metadataCompletionTransition" role="status" aria-live="polite"><span>Metadata complete</span><strong>Preparing structured table</strong></section>;
  return <section className="findabilityEnrichmentGate findabilityGuidedEditor reusabilityGuidedEditor" aria-label="Reusability guided editor">
    <header><span>Reusability enrichment</span><h3>Make this Knowledge Object reusable</h3></header>
    <div className="guidedEditorFields">
      <article className={state.scope ? "complete guidedField guidedTextField" : "missing guidedField guidedTextField"}><div className="guidedFieldHeading"><label htmlFor="reusability-scope"><strong>Scope</strong><small>Enter more than 10 characters describing appropriate use.</small></label><button type="button" onClick={() => { setScope(simulatedScope); construct({ scope: simulatedScope }); }}>Assist Me</button></div><textarea id="reusability-scope" value={scope} onChange={(event) => { const next = event.target.value; setScope(next); construct({ scope: next }); }} rows={3} /><span>{scope.trim().length > 10 ? "Complete" : "Needs more detail"}</span></article>
      <article className={state.license ? "complete guidedField guidedCheckboxField" : "missing guidedField guidedCheckboxField"}><div><strong>License</strong><small>Confirm the declared terms governing permitted reuse.</small></div><div className="guidedCheckList">{licenseOptions.map((option) => <label className="guidedCheckRow" key={option.iri}><input type="checkbox" checked={selectedLicenses.includes(option.iri)} onChange={(event) => construct({ licenseIris: event.target.checked ? [...selectedLicenses, option.iri] : selectedLicenses.filter((iri) => iri !== option.iri) })} /><span><b>{option.label}</b><small>{option.description}</small><code>{option.iri}</code></span></label>)}</div><span>{selectedLicenses.length} selected · {state.license ? "Complete" : "Needs work"}</span></article>
      <article className={state.evidence ? "complete guidedField guidedCheckboxField" : "missing guidedField guidedCheckboxField"}><div><strong>Evidence</strong><small>Select both declared records supporting the knowledge represented by this object.</small></div><div className="guidedCheckList evidenceCheckList">{evidenceOptions.map((option) => <label className="guidedCheckRow" key={option.iri}><input type="checkbox" checked={selectedEvidence.includes(option.iri)} onChange={(event) => construct({ evidenceIris: event.target.checked ? [...selectedEvidence, option.iri] : selectedEvidence.filter((iri) => iri !== option.iri) })} /><span><b>{option.citation}</b><small>{option.identifier}</small></span></label>)}</div><span>{selectedEvidence.length} of {evidenceOptions.length} selected · {state.evidence ? "Complete" : "Needs work"}</span></article>
    </div>
  </section>;
}

function WorkspacePane({
  side,
  objectId,
  otherObjectId,
  file,
  drafts,
  onObjectChange,
  onFileChange,
  onEdit,
  onReset,
  showObjectSelector = true,
}: {
  side: "Left" | "Right" | "Metadata";
  objectId: ObjectId;
  otherObjectId: ObjectId;
  file: FileName;
  drafts: Drafts;
  onObjectChange: (id: ObjectId) => void;
  onFileChange: (file: FileName) => void;
  onEdit: (value: string) => void;
  onReset: () => void;
  showObjectSelector?: boolean;
}) {
  const [rdfView, setRdfView] = useState<"human" | "source">("human");
  const [relationshipOpen, setRelationshipOpen] = useState(false);
  const [resetConfirmationOpen, setResetConfirmationOpen] = useState(false);
  const [principlesOpen, setPrinciplesOpen] = useState(false);
  const [uniqueKoIdOnly, setUniqueKoIdOnly] = useState(false);
  const [uniqueKoMetadataIdOnly, setUniqueKoMetadataIdOnly] = useState(false);
  const [koAccessOnly, setKoAccessOnly] = useState(false);
  const [koMetadataAccessOnly, setKoMetadataAccessOnly] = useState(false);
  const [specifiedInterfaceOnly, setSpecifiedInterfaceOnly] = useState(false);
  const [objectReferencesOnly, setObjectReferencesOnly] = useState(false);
  const [licenseOnly, setLicenseOnly] = useState(false);
  const [dependenciesOnly, setDependenciesOnly] = useState(false);
  if (objectId === 0) {
    return (
      <section className="pane" aria-label={`${side} editor pane`}>
        <div className="paneHead">
          <div><h2>Select a knowledge object</h2></div>
          <label className="selectWrap">
            <span className="srOnly">Choose knowledge object for {side.toLowerCase()} pane</span>
            <select value="" onChange={(event) => { setUniqueKoIdOnly(false); setUniqueKoMetadataIdOnly(false); setKoAccessOnly(false); setKoMetadataAccessOnly(false); setSpecifiedInterfaceOnly(false); setObjectReferencesOnly(false); setLicenseOnly(false); setDependenciesOnly(false); onObjectChange(Number(event.target.value) as ObjectId); }}>
              <option value="" disabled>Choose object…</option>
              {OBJECT_IDS.map((id) => (
                <option key={id} value={id} disabled={id === otherObjectId}>{objectName(id)}{id === otherObjectId ? " · in use" : ""}</option>
              ))}
            </select>
          </label>
        </div>
        <div className="emptyPane">
          <strong>No Knowledge Object Loaded</strong>
          <p>Choose a knowledge object above to begin.</p>
        </div>
      </section>
    );
  }

  const value = workingFileValue(objectId, file, drafts);
  const modified = value !== seedValue(objectId, file);
  const isTurtle = /^\s*@prefix\s+/m.test(value) && /(?:^|\n)\s*[^#\s].*[.;]\s*$/m.test(value);
  const turtleDiagnostics = isTurtle ? buildCanonicalRdfGraph(value).diagnostics : [];
  const visibleFiles: readonly FileName[] = metadataFilesForObject(objectId);
  const isFindabilityEnrichmentTarget = objectId === findabilityEnrichmentTargetObjectId && file === FINDABILITY_ENRICHMENT_FILE;
  const findabilityEnrichment = isFindabilityEnrichmentTarget ? getFindabilityUnlockState(value) : null;
  const findabilityNeedsGuidedEntry = Boolean(findabilityEnrichment && !findabilityEnrichment.unlocked);
  const isReusabilityEnrichmentTarget = objectId === reusabilityEnrichmentTargetObjectId && file === REUSABILITY_ENRICHMENT_FILE;
  const reusabilityEnrichment = isReusabilityEnrichmentTarget ? getReusabilityUnlockState(value) : null;
  const reusabilityNeedsGuidedEntry = Boolean(reusabilityEnrichment && !reusabilityEnrichment.unlocked);
  const metadataNeedsGuidedEntry = findabilityNeedsGuidedEntry || reusabilityNeedsGuidedEntry;

  return (
    <section className="pane" aria-label={`${side} editor pane`}>
      <div className="paneHead">
        <div>
          <h2>{objectName(objectId)}</h2>
        </div>
        {showObjectSelector && <label className="selectWrap">
          <span className="srOnly">Choose knowledge object for {side.toLowerCase()} pane</span>
          <select
            value={objectId}
            onChange={(event) => { setUniqueKoIdOnly(false); setUniqueKoMetadataIdOnly(false); setKoAccessOnly(false); setKoMetadataAccessOnly(false); setSpecifiedInterfaceOnly(false); setObjectReferencesOnly(false); setLicenseOnly(false); setDependenciesOnly(false); onObjectChange(Number(event.target.value) as ObjectId); }}
          >
            {OBJECT_IDS.map((id) => (
              <option key={id} value={id} disabled={id === otherObjectId}>
                {objectName(id)}{id === otherObjectId ? " · in use" : ""}
              </option>
            ))}
          </select>
        </label>}
      </div>

      <div className="paneBody">
        <nav className="fileRail" aria-label={`${side} knowledge object files`}>
          <div className="railTitle">
            <span>Files</span>
            <span className="count">{visibleFiles.length}</span>
          </div>
          {visibleFiles.map((fileName) => {
            return (
              <button
                key={fileName}
                className={fileName === file ? "fileButton active" : "fileButton"}
                onClick={() => { setUniqueKoIdOnly(false); setUniqueKoMetadataIdOnly(false); setKoAccessOnly(false); setKoMetadataAccessOnly(false); setSpecifiedInterfaceOnly(false); setObjectReferencesOnly(false); setLicenseOnly(false); setDependenciesOnly(false); onFileChange(fileName); }}
                title={fileName}
              >
                <span className="fileIcon" aria-hidden="true">{fileName.endsWith(".json") ? "{}" : "T"}</span>
                <span className="fileName">{fileName}</span>
              </button>
            );
          })}
        </nav>

        <div className="editorColumn">
          <div className="editorBar">
            {modified && <button className="editorControlButton editorResetButton" type="button" onClick={() => setResetConfirmationOpen(true)}>Reset</button>}
            {file === "metadata.json" && <button className="informationPageButton" type="button" onClick={() => openEmbeddedInformationPage(objectId)}>Information Page</button>}
            {PRINCIPLES_LABELS[file] && <button className={principlesOpen ? "informationPageButton active" : "informationPageButton"} type="button" aria-expanded={principlesOpen} aria-controls="principles-control-row" onClick={() => setPrinciplesOpen((open) => { if (open) { setUniqueKoIdOnly(false); setUniqueKoMetadataIdOnly(false); setKoAccessOnly(false); setKoMetadataAccessOnly(false); setSpecifiedInterfaceOnly(false); setObjectReferencesOnly(false); setLicenseOnly(false); setDependenciesOnly(false); } return !open; })}>{PRINCIPLES_LABELS[file]}</button>}
            <div className="editorControls">
              {isTurtle && !metadataNeedsGuidedEntry && <button className="editorControlButton" type="button" onClick={() => setRelationshipOpen(true)} disabled={turtleDiagnostics.length > 0} title={turtleDiagnostics.length ? "Correct the Turtle source before graphing it" : undefined}>Graph</button>}
              {isTurtle && !metadataNeedsGuidedEntry && <div className="rdfViewControl" role="group" aria-label="RDF presentation">{(["human", "source"] as const).map((mode) => <button type="button" key={mode} className={rdfView === mode ? "active" : ""} aria-pressed={rdfView === mode} onClick={() => setRdfView(mode)}>{mode === "human" ? "Table" : "Source"}</button>)}</div>}
            </div>
          </div>
          {PRINCIPLES_LABELS[file] && principlesOpen && <div id="principles-control-row" className="principlesControlRow" role="group" aria-label={`${PRINCIPLES_LABELS[file]} controls`}><div className="principlesTrayButtons">{PRINCIPLES_CONTROLS[file].map((label) => label === "Unique KO ID" && file === "findability.metadata.txt" ? <button key={label} className={`principlesTrayButton${uniqueKoIdOnly ? " active" : ""}`} type="button" aria-pressed={uniqueKoIdOnly} onClick={() => { setUniqueKoIdOnly((active) => !active); setRdfView("human"); }}>{label}</button> : label === "Unique KO Metadata ID" && file === "findability.metadata.txt" ? <button key={label} className={`principlesTrayButton${uniqueKoMetadataIdOnly ? " active" : ""}`} type="button" aria-pressed={uniqueKoMetadataIdOnly} onClick={() => { setUniqueKoMetadataIdOnly((active) => !active); setRdfView("human"); }}>{label}</button> : label === "KO Access" && file === "access.metadata.txt" ? <button key={label} className={`principlesTrayButton${koAccessOnly ? " active" : ""}`} type="button" aria-pressed={koAccessOnly} onClick={() => { setKoAccessOnly((active) => !active); setRdfView("human"); }}>{label}</button> : label === "KO Metadata Access" && file === "access.metadata.txt" ? <button key={label} className={`principlesTrayButton${koMetadataAccessOnly ? " active" : ""}`} type="button" aria-pressed={koMetadataAccessOnly} onClick={() => { setKoMetadataAccessOnly((active) => !active); setRdfView("human"); }}>{label}</button> : label === "Specified Interface" && file === "interoperability.metadata.txt" ? <button key={label} className={`principlesTrayButton${specifiedInterfaceOnly ? " active" : ""}`} type="button" aria-pressed={specifiedInterfaceOnly} onClick={() => { setSpecifiedInterfaceOnly((active) => !active); setRdfView("human"); }}>{label}</button> : label === "Object References" && file === "interoperability.metadata.txt" ? <button key={label} className={`principlesTrayButton${objectReferencesOnly ? " active" : ""}`} type="button" aria-pressed={objectReferencesOnly} onClick={() => { setObjectReferencesOnly((active) => !active); setRdfView("human"); }}>{label}</button> : label === "License" && file === "reusability.metadata.txt" ? <button key={label} className={`principlesTrayButton${licenseOnly ? " active" : ""}`} type="button" aria-pressed={licenseOnly} onClick={() => { setLicenseOnly((active) => !active); setRdfView("human"); }}>{label}</button> : label === "Dependencies" && file === "reusability.metadata.txt" ? <button key={label} className={`principlesTrayButton${dependenciesOnly ? " active" : ""}`} type="button" aria-pressed={dependenciesOnly} onClick={() => { setDependenciesOnly((active) => !active); setRdfView("human"); }}>{label}</button> : <button key={label} className="principlesTrayButton" type="button">{label}</button>)}</div><a className="principlesReference" href="https://zenodo.org/records/6623556#.YqCJTJNBwlw" target="_blank" rel="noreferrer">Based on FAIR Principles<br />for Research Software</a></div>}
          {findabilityNeedsGuidedEntry && findabilityEnrichment ? <FindabilityGuidedEditor value={value} canonicalSource={findabilityEnrichmentCanonicalSource} state={findabilityEnrichment} onEdit={(nextValue) => { setRdfView("human"); onEdit(nextValue); }} /> : reusabilityNeedsGuidedEntry && reusabilityEnrichment ? <ReusabilityGuidedEditor value={value} canonicalSource={reusabilityEnrichmentCanonicalSource} metadataSource={workingFileValue(objectId, "metadata.json", drafts)} state={reusabilityEnrichment} onEdit={(nextValue) => { setRdfView("human"); onEdit(nextValue); }} /> : isTurtle && rdfView === "human" ? <HumanRdfView source={value} file={file} baselineSource={isFindabilityEnrichmentTarget ? findabilityEnrichmentBaseline : isReusabilityEnrichmentTarget ? reusabilityEnrichmentBaseline : undefined} uniqueKoIdOnly={uniqueKoIdOnly && file === "findability.metadata.txt"} uniqueKoMetadataIdOnly={uniqueKoMetadataIdOnly && file === "findability.metadata.txt"} koAccessOnly={koAccessOnly && file === "access.metadata.txt"} koMetadataAccessOnly={koMetadataAccessOnly && file === "access.metadata.txt"} specifiedInterfaceOnly={specifiedInterfaceOnly && file === "interoperability.metadata.txt"} objectReferencesOnly={objectReferencesOnly && file === "interoperability.metadata.txt"} licenseOnly={licenseOnly && file === "reusability.metadata.txt"} dependenciesOnly={dependenciesOnly && file === "reusability.metadata.txt"} /> : <>{isTurtle && turtleDiagnostics.length > 0 && <div className="sourceValidation" role="alert"><strong>Invalid Turtle source</strong><span>{turtleDiagnostics[0]}</span></div>}<textarea
            value={value}
            onChange={(event) => onEdit(event.target.value)}
            spellCheck={false}
            aria-label={`Editing ${file} from ${objectName(objectId)}`}
          /></>}
          <div className="editorFooter">
            <span>{metadataNeedsGuidedEntry ? "Guided metadata entry" : isTurtle ? rdfView === "human" ? "RDF table projection" : "Authoritative Turtle source" : "Plain text"}</span>
            <span>{value.length} characters</span>
          </div>
          {relationshipOpen && <RelationshipDialog source={value} title={`${objectName(objectId)} · ${file}`} onClose={() => setRelationshipOpen(false)} />}
          {resetConfirmationOpen && createPortal(<ResetConfirmationDialog onCancel={() => setResetConfirmationOpen(false)} onConfirm={() => { setResetConfirmationOpen(false); onReset(); }} />, document.body)}
        </div>
      </div>
    </section>
  );
}

class MetadataInteractionErrorBoundary extends Component<{ children: ReactNode; objectId: ObjectId; file: FileName; onFileChange: (file: FileName) => void }, { error: Error | null }> {
  state = { error: null as Error | null };
  static getDerivedStateFromError(error: Error) { return { error }; }
  componentDidCatch(error: Error, info: ErrorInfo) { console.error("Metadata Interaction failed", error, info); }
  render() {
    if (!this.state.error) return this.props.children;
    const { objectId, file, onFileChange } = this.props;
    const visibleFiles = metadataFilesForObject(objectId);
    return <section className="pane" aria-label="Metadata editor pane">
      <div className="paneHead"><div><h2>{objectName(objectId)}</h2></div></div>
      <div className="paneBody">
        <nav className="fileRail" aria-label="Metadata knowledge object files">
          <div className="railTitle"><span>Files</span><span className="count">{visibleFiles.length}</span></div>
          {visibleFiles.map((fileName) => <button type="button" key={fileName} className={fileName === file ? "fileButton active" : "fileButton"} onClick={() => onFileChange(fileName)} title={fileName}><span className="fileIcon" aria-hidden="true">{fileName.endsWith(".json") ? "{}" : "T"}</span><span className="fileName">{fileName}</span></button>)}
        </nav>
        <div className="editorColumn"><div className="metadataFileError" role="alert"><strong>Unable to display {file}</strong><p>{this.state.error.message}</p><small>Select another file or close Metadata Interaction.</small></div></div>
      </div>
    </section>;
  }
}

function AssemblyKoExchangeView({ exchange, name, caseNumber, onClose }: { exchange: NonNullable<ReturnType<typeof projectAssemblyKoExchange>>; name: string; caseNumber: number; onClose: () => void }) {
  const [mode, setMode] = useState<"table" | "source">("table");
  const closeRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    const returnFocus = document.activeElement as HTMLElement | null;
    closeRef.current?.focus();
    const onEscape = (event: globalThis.KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    document.addEventListener("keydown", onEscape);
    return () => { document.removeEventListener("keydown", onEscape); returnFocus?.focus(); };
  }, [onClose]);
  const renderPart = (part: "input" | "output" | "handoff") => <section className="assemblyKoExchangeSection" aria-label={part}>
    <h3>{part === "handoff" ? "Handoff" : part === "input" ? "Input" : "Output"}</h3>
    {mode === "table" ? <><p>{exchange[part].summary}</p>{exchange[part].sections.map((section) => <div key={section.heading} className="assemblyKoExchangeGroup"><h4>{section.heading}</h4><dl>{section.items.map((item: { label: string; value: string }) => <div key={`${section.heading}-${item.label}`}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl></div>)}</> : <pre>{JSON.stringify(exchange[part].source, null, 2)}</pre>}
  </section>;
  return createPortal(<div className="assemblyKoExchangeBackdrop" role="dialog" aria-modal="true" aria-label={`${name} Case ${caseNumber} contribution`}>
    <div className="assemblyKoExchangeHeader"><span>Case {caseNumber} · KO contribution</span><h2>{name}</h2><button ref={closeRef} type="button" aria-label="Close KO contribution" onClick={onClose}>×</button></div>
    <div className="assemblyKoExchangeControls" aria-label="Contribution display"><button type="button" className={mode === "table" ? "selected" : ""} aria-pressed={mode === "table"} onClick={() => setMode("table")}>Table</button><button type="button" className={mode === "source" ? "selected" : ""} aria-pressed={mode === "source"} onClick={() => setMode("source")}>Source</button></div>
    <div className="assemblyKoExchangeBody">{renderPart("input")}<div className="assemblyKoExchangeSecondary">{renderPart("output")}{renderPart("handoff")}</div></div>
  </div>, document.body);
}

function KnowledgeAssemblyCaseView() {
  const [puzzlePieceOrder] = useState(shuffleAssemblyPuzzlePieces);
  const [puzzleComplete, setPuzzleComplete] = useState(false);
  const [puzzlePlacement, setPuzzlePlacement] = useState<Record<string, string>>({});
  const [selectedPuzzlePiece, setSelectedPuzzlePiece] = useState<string | null>(null);
  const [puzzleMessage, setPuzzleMessage] = useState("Select a Knowledge Object, then choose a position; or drag it there.");
  const firstPuzzlePieceRef = useRef<HTMLButtonElement>(null);
  const firstCaseRef = useRef<HTMLButtonElement>(null);
  const [selectedCaseId, setSelectedCaseId] = useState("case-1");
  const [selectedKoRole, setSelectedKoRole] = useState<string | null>(null);
  const loaded = loadAssemblyTeachingCases(EMBEDDED_ASSEMBLY);
  const selectedCase = loaded.cases.find((item) => item.id === selectedCaseId) ?? loaded.cases[0];
  const selectedIndex = selectedCase ? loaded.cases.indexOf(selectedCase) + 1 : 0;
  const inputs = selectedCase ? projectAssemblyCaseInputs(selectedCase.request) : null;
  const contributions = selectedCase ? projectAssemblyKoContributions(selectedCase.semanticTrace) : null;
  const kaDecisions = selectedCase ? projectAssemblyKaDecisions(selectedCase.semanticTrace) : null;
  const synthesisMatrix = selectedCase && EMBEDDED_ASSEMBLY ? projectAssemblySynthesisMatrix(EMBEDDED_ASSEMBLY, selectedCase.semanticTrace) : null;
  const puzzleCheck = evaluateAssemblyPuzzle(puzzlePlacement);
  const puzzleFeedback = puzzleCheck.status === "workable" ? "This arrangement can be orchestrated."
    : puzzleCheck.status === "unworkable" ? assemblyPuzzleFailureMessage(puzzleCheck.reason)
    : puzzleMessage;
  const puzzleResetTimer = useRef<number | null>(null);
  const focusAfterPuzzleReset = useRef(false);
  useEffect(() => () => { if (puzzleResetTimer.current) window.clearTimeout(puzzleResetTimer.current); }, []);
  useEffect(() => { if (puzzleComplete) firstCaseRef.current?.focus(); }, [puzzleComplete]);
  useEffect(() => {
    if (focusAfterPuzzleReset.current) {
      focusAfterPuzzleReset.current = false;
      firstPuzzlePieceRef.current?.focus();
    }
  }, [puzzlePlacement]);
  if (!EMBEDDED_ASSEMBLY) return null;
  const puzzleName = (role: string) => objectName(({ wagner: 1, decision: 2, margolis: 4, burden: 3 } as Record<string, number>)[role]);
  const placePuzzlePiece = (role: string, targetSlot: string | null) => {
    const next = moveAssemblyPuzzlePiece(puzzlePlacement, role, targetSlot);
    const check = evaluateAssemblyPuzzle(next);
    setPuzzlePlacement(next);
    setSelectedPuzzlePiece(null);
    setPuzzleMessage(targetSlot ? `${puzzleName(role)} moved to position ${ASSEMBLY_PUZZLE_SLOTS.indexOf(targetSlot) + 1}.` : `${puzzleName(role)} returned to the starting area.`);
    if (check.status === "workable") {
      setSelectedCaseId("case-1");
      setPuzzleComplete(true);
    } else if (check.status === "unworkable") {
      const failure = assemblyPuzzleFailureMessage(check.reason);
      puzzleResetTimer.current = window.setTimeout(() => {
        focusAfterPuzzleReset.current = true;
        setPuzzlePlacement({});
        setSelectedPuzzlePiece(null);
        setPuzzleMessage(`${failure} All four KOs have returned to the starting area. Try again.`);
        puzzleResetTimer.current = null;
      }, 1800);
    }
  };

  const exchange = selectedKoRole && selectedCase ? projectAssemblyKoExchange(selectedCase, selectedKoRole) : null;
  return <><section className="knowledgeObjectsExercise assemblyExercise" aria-label="Knowledge Assembly explorer">
    <div className="viewStickyControls">
      <div className="viewTitle"><h2>Assembly Orchestration</h2></div>
      {!puzzleComplete && !loaded.error && <p className="assemblyPuzzleInstruction">Arrange the four Knowledge Objects so the severity score feeds the treatment decision. The treatment decision, regimen burden estimate, and prognostic indicator then contribute to the assembly’s treatment-target classification.</p>}
    </div>
    {loaded.error ? <div className="assemblyWorkspaceError" role="alert">{loaded.error}</div> :
      !puzzleComplete ? <div className="assemblyWorkspace assemblyPuzzleWorkspace">
        <aside className="assemblyPuzzlePieces" aria-label="Knowledge Objects to assemble" onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); const role = event.dataTransfer.getData("text/plain"); if (ASSEMBLY_PUZZLE_PIECES.includes(role)) placePuzzlePiece(role, null); }}>
          <h3>Knowledge Objects</h3>
          <div className="assemblyPuzzlePieceList">
            {puzzlePieceOrder.filter((role) => !Object.values(puzzlePlacement).includes(role)).map((role) => <button type="button" className={`assemblyPuzzlePiece${selectedPuzzlePiece === role ? " selected" : ""}`} data-assembly-piece={role} key={role} ref={role === puzzlePieceOrder[0] ? firstPuzzlePieceRef : undefined} draggable aria-pressed={selectedPuzzlePiece === role} onClick={() => setSelectedPuzzlePiece(selectedPuzzlePiece === role ? null : role)} onDragStart={(event) => { setSelectedPuzzlePiece(role); event.dataTransfer.setData("text/plain", role); }}>{puzzleName(role)}</button>)}
          </div>
          <button type="button" className="assemblyPuzzleReturn" disabled={!selectedPuzzlePiece} onClick={() => selectedPuzzlePiece && placePuzzlePiece(selectedPuzzlePiece, null)}>Return selected KO here</button>
        </aside>
        <section className="assemblyPuzzleBoard" aria-label="Assembly puzzle">
          <div className="assemblyPuzzleSlots" aria-label="Four Knowledge Object positions">
            {ASSEMBLY_PUZZLE_SLOTS.map((slot, index) => <button type="button" className={`assemblyPuzzleSlot${puzzlePlacement[slot] ? " occupied" : ""}${selectedPuzzlePiece === puzzlePlacement[slot] ? " selected" : ""}`} data-assembly-slot={slot} aria-label={puzzlePlacement[slot] ? `Position ${index + 1}: ${puzzleName(puzzlePlacement[slot])}` : `Empty Knowledge Object position ${index + 1}`} aria-pressed={Boolean(puzzlePlacement[slot] && selectedPuzzlePiece === puzzlePlacement[slot])} draggable={Boolean(puzzlePlacement[slot])} onClick={() => { if (selectedPuzzlePiece) placePuzzlePiece(selectedPuzzlePiece, slot); else if (puzzlePlacement[slot]) setSelectedPuzzlePiece(puzzlePlacement[slot]); }} onDragStart={(event) => { if (!puzzlePlacement[slot]) return; setSelectedPuzzlePiece(puzzlePlacement[slot]); event.dataTransfer.setData("text/plain", puzzlePlacement[slot]); }} onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); const role = event.dataTransfer.getData("text/plain"); if (ASSEMBLY_PUZZLE_PIECES.includes(role)) placePuzzlePiece(role, slot); }} key={slot}><span>{puzzlePlacement[slot] ? puzzleName(puzzlePlacement[slot]) : "Place KO here"}</span></button>)}
          </div>
          <p className={`assemblyPuzzleMessage${puzzleCheck.status !== "incomplete" ? ` ${puzzleCheck.status}` : ""}`} role="status">{puzzleFeedback}</p>
          <div className="assemblyFlowToAssembly" aria-label="The second, third, and fourth positions feed the assembly"><span aria-hidden="true" /><span className="assemblyFlowArrow" aria-hidden="true" /><span className="assemblyFlowArrow" aria-hidden="true" /><span className="assemblyFlowArrow" aria-hidden="true" /></div>
          <div className="assemblyPuzzleDestination">Assembly decisions</div>
        </section>
      </div> : <div className="assemblyWorkspace">
        <nav className="assemblyCaseSelector" aria-label="Teaching cases">
          <h3>Cases</h3>
          <div className="assemblyCaseButtons">
            {loaded.cases.map((item, index) => <button type="button" key={item.id} ref={index === 0 ? firstCaseRef : undefined}
              className={item.id === selectedCase?.id ? "selected" : ""}
              aria-pressed={item.id === selectedCase?.id}
              onClick={() => { setSelectedKoRole(null); setSelectedCaseId(item.id); }}>
              Case {index + 1}
            </button>)}
          </div>
        </nav>
        {selectedCase && <article className="assemblyCaseDetail" aria-label={`Case ${selectedIndex} details`}>
          <div className="assemblyCaseSummary">
            {inputs && <section className="assemblyInputsPanel" aria-label="Case inputs">
              <dl className="assemblyInputFacts">
                <div><dt>Person</dt><dd>Person {selectedIndex}</dd></div>
                <div><dt>Ulcer / site</dt><dd>Ulcer {selectedIndex}</dd></div>
                {inputs.facts.map((fact) => <div key={fact.label}><dt>{fact.label}</dt><dd className={fact.label === "Diabetic foot ulcer" && fact.value === "Not confirmed" ? "notConfirmed" : undefined}>{fact.value}</dd></div>)}
              </dl>
            </section>}
            {contributions && <section className="assemblyOrchestration" aria-label="KO contributions and handoffs">
              <div className="assemblyKoModules">
                <article className="assemblyKoModule assemblyKoModuleInteractive">
                  <h5>{objectName(1)}</h5><strong>{contributions.wagner.result}</strong><p className="assemblyKoDetail">{contributions.wagner.detail}</p>
                  <button type="button" className="assemblyKoInspectButton" aria-label={`Inspect ${objectName(1)} input, output, and handoff for Case ${selectedIndex}`} onClick={() => setSelectedKoRole("wagner")}>I/O</button>
                  <span className="srOnly">{contributions.wagner.entry}. The Wagner grade is handed to HBOT Decision.</span>
                </article>
                <article className="assemblyKoModule assemblyKoModuleInteractive">
                  <h5>{objectName(2)}</h5><strong>{contributions.decision.result}</strong><p className="assemblyKoDetail">{contributions.decision.detail}</p>
                  <button type="button" className="assemblyKoInspectButton" aria-label={`Inspect ${objectName(2)} input, output, and handoff for Case ${selectedIndex}`} onClick={() => setSelectedKoRole("decision")}>I/O</button>
                  <span className="srOnly">{contributions.decision.entry}. {contributions.decision.exit}.</span>
                </article>
                <article className="assemblyKoModule assemblyKoModuleInteractive">
                  <h5>{objectName(4)}</h5><strong>{contributions.margolis.result}</strong><p className="assemblyKoDetail">{contributions.margolis.detail}</p>
                  <button type="button" className="assemblyKoInspectButton" aria-label={`Inspect ${objectName(4)} input, output, and handoff for Case ${selectedIndex}`} onClick={() => setSelectedKoRole("margolis")}>I/O</button>
                  <span className="srOnly">{contributions.margolis.entry}. {contributions.margolis.exit ?? "No synthesis handoff in this case"}.</span>
                </article>
                <article className="assemblyKoModule assemblyKoModuleInteractive">
                  <h5>{objectName(3)}</h5><strong>{contributions.burden.result}</strong><p className="assemblyKoDetail">{contributions.burden.detail}</p>
                  <button type="button" className="assemblyKoInspectButton" aria-label={`Inspect ${objectName(3)} input, output, and handoff for Case ${selectedIndex}`} onClick={() => setSelectedKoRole("burden")}>I/O</button>
                  <span className="srOnly">{contributions.burden.entry}. {contributions.burden.exit ?? "No synthesis handoff in this case"}.</span>
                </article>
              </div>
              <div className="assemblyFlowToAssembly" aria-label="HBOT Decision, Margolis, and Burden outputs feed Assembly decisions">
                <span aria-hidden="true" /><span className="assemblyFlowArrow" aria-hidden="true" /><span className="assemblyFlowArrow" aria-hidden="true" /><span className="assemblyFlowArrow" aria-hidden="true" />
              </div>
            </section>}
            {kaDecisions && <section className="assemblyDecisionSequence" aria-label="Knowledge Assembly decisions">
              <div className="assemblyDecisionLayout">
                <article className="assemblyIntermediateCard">
                  <h5>Assembly stages</h5>
                  <div className="assemblyStageGrid">
                    <div className="assemblyStageCard"><span>1. Four KO Output Checks</span><strong>{kaDecisions.join.result === "Four-KO join passed" ? "Passed" : kaDecisions.join.result}</strong></div>
                    <div className="assemblyStageCard"><span>2. HBOT use</span><strong>{kaDecisions.gate.result}</strong></div>
                    <div className="assemblyStageCard assemblyStageSelection"><span>3. Matrix selection</span><strong>{kaDecisions.bands ? `${kaDecisions.bands[0].result} + ${kaDecisions.bands[1].result}` : "Not applied"}</strong></div>
                  </div>
                </article>
                <article className="assemblyMatrixCard">
                  <h5>Assembly output</h5>
                  {synthesisMatrix?.error ? <p role="alert">{synthesisMatrix.error}</p> : <>
                    <div className="assemblyMatrixColumns" aria-hidden="true"><span></span><span>Lower burden</span><span>Middle burden</span><span>Higher burden</span></div>
                    <div className="assemblyMatrixGrid" role="grid" aria-label="Twelve synthesis categories">
                      {["VERY_UNFAVORABLE", "UNFAVORABLE", "INTERMEDIATE", "RELATIVELY_FAVORABLE"].map((band) => <div className="assemblyMatrixRow" role="row" key={band}>
                        <span className="assemblyMatrixRowLabel">{band.toLowerCase().replaceAll("_", " ")} prognosis</span>
                        {synthesisMatrix?.cells.filter((cell) => cell.prognosis === `${band}_PROGNOSIS_BAND`).map((cell) => <div role="gridcell" aria-selected={cell.rule === synthesisMatrix.selectedRule} className={`assemblyMatrixCell ${cell.rule === synthesisMatrix.selectedRule ? "selected" : ""}`} key={cell.rule}>
                          <strong><span>{cell.classification.toLowerCase().replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase())} for</span><span>HBOT Therapy</span></strong>
                        </div>)}
                      </div>)}
                    </div>
                  </>}
                </article>
              </div>
            </section>}
          </div>
        </article>}
      </div>}
  </section>{exchange && <AssemblyKoExchangeView exchange={exchange} name={objectName(({ wagner: 1, decision: 2, margolis: 4, burden: 3 } as Record<string, number>)[exchange.role])} caseNumber={selectedIndex} onClose={() => setSelectedKoRole(null)} />}</>;
}

function KnowledgeAssemblyWorkspace({ assemblyLoaded, onLoad }: { assemblyLoaded: boolean; onLoad: () => void }) {
  const [caseViewOpen, setCaseViewOpen] = useState(false);
  const [loadPressing, setLoadPressing] = useState(false);
  const closeRef = useRef<HTMLButtonElement>(null);
  const assemblyTitle = typeof EMBEDDED_ASSEMBLY?.metadata["dc:title"] === "string" ? EMBEDDED_ASSEMBLY.metadata["dc:title"] : "Knowledge Assembly";
  useEffect(() => {
    if (!caseViewOpen) return;
    const returnFocus = document.activeElement as HTMLElement | null;
    closeRef.current?.focus();
    const onEscape = (event: KeyboardEvent) => { if (event.key === "Escape" && !document.querySelector(".assemblyKoExchangeBackdrop")) setCaseViewOpen(false); };
    document.addEventListener("keydown", onEscape);
    return () => { document.removeEventListener("keydown", onEscape); returnFocus?.focus(); };
  }, [caseViewOpen]);
  if (!EMBEDDED_ASSEMBLY) return null;
  return <>
    <section className="knowledgeObjectsExercise assemblyLanding" aria-label="Knowledge Assembly explorer">
      <div className="viewStickyControls">
        <div className="viewTitle"><div className="koInstrumentMark">KA</div><h2>Knowledge Assembly</h2></div>
        <p>Explore the assembly of Knowledge Objects</p>
      </div>
      <article className="assemblyObjectBar"><strong>{assemblyTitle}</strong><button type="button" onClick={() => setCaseViewOpen(true)}>Orchestration</button></article>
      <div className="assemblyLoadControl">{assemblyLoaded
        ? <span className="assemblyLoadedStatus" role="status">Loaded as a Knowledge Object</span>
        : <button type="button" className={loadPressing ? "isPressing" : undefined} disabled={loadPressing} onClick={() => { setLoadPressing(true); window.setTimeout(onLoad, 220); }}>Load as Knowledge Object</button>}
      </div>
    </section>
    {caseViewOpen && createPortal(<div className="assemblyCaseBackdrop" role="dialog" aria-modal="true" aria-label="Orchestration">
      <button ref={closeRef} type="button" className="assemblyCaseClose" aria-label="Close orchestration" onClick={() => setCaseViewOpen(false)}>×</button>
      <KnowledgeAssemblyCaseView />
    </div>, document.body)}
  </>;
}

export default function Home() {
  const [, setLeftObject] = useState<ObjectId>(0);
  const [leftFile, setLeftFile] = useState<FileName>(FILTERED_FILES[0]);
  const [drafts, setDrafts] = useState<Drafts>({});
  const [activeExercise, setActiveExercise] = useState<"K" | "F" | "A" | "I" | "R" | null>(null);
  const [openKnowledgeSubgraph, setOpenKnowledgeSubgraph] = useState<{ objectId: ObjectId; model: ReturnType<typeof projectKnowledgeViewModel>; metadata: Record<string, unknown> | null } | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [submittedSearchQuery, setSubmittedSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<SearchResult[] | null>(null);
  const [openFindabilityResults, setOpenFindabilityResults] = useState<{ objectId: ObjectId; query: string; results: SearchResult[] } | null>(null);
  const [openFindabilityAudit, setOpenFindabilityAudit] = useState<{ objectId: ObjectId; rows: FindabilityAuditRow[] } | null>(null);
  const [interoperabilitySessions, setInteroperabilitySessions] = useState<Partial<Record<ObjectId, InteroperabilitySimulationSession>>>({});
  const [interoperabilityStagesObject, setInteroperabilityStagesObject] = useState<ObjectId | null>(null);
  const [abstractOpen, setAbstractOpen] = useState(false);
  const [openTest, setOpenTest] = useState<{ objectId: ObjectId; file: FileName } | null>(null);
  const [openEvidence, setOpenEvidence] = useState<{ objectId: ObjectId; file: FileName } | null>(null);
  const [accessErrors, setAccessErrors] = useState<Partial<Record<ObjectId, string>>>({});
  const [workspaceView, setWorkspaceView] = useState<"files" | "objects" | "assembly">("objects");
  const [activeObjects, setActiveObjects] = useState(() => createInitialActiveObjects(OBJECT_IDS));
  const activeObjectIds: ObjectId[] = useMemo(() => activeObjects.map((object) => object.kind === "knowledge-assembly" ? ASSEMBLY_OBJECT_ID : object.objectId), [activeObjects]);
  const [metadataInteractObject, setMetadataInteractObject] = useState<ObjectId | null>(null);
  const [koPanelReset, setKoPanelReset] = useState(0);

  useEffect(() => {
    const access = createKnowledgeObjectAccessApi({
      objects: KO_ACCESS_OBJECTS.filter((object) => activeObjectIds.includes(object.sourceIndex)),
      getEmbeddedFiles: async (object: { sourceIndex: ObjectId }) => Promise.all(filesForObject(object.sourceIndex).map(async (path) => ({ path, content: await embeddedFileValue(object.sourceIndex, path) }))),
      getWorkingFiles: async (object: { sourceIndex: ObjectId }) => Promise.all(filesForObject(object.sourceIndex).map(async (path) => ({ path, content: Object.hasOwn(drafts, draftKey(object.sourceIndex, path)) ? drafts[draftKey(object.sourceIndex, path)] : await embeddedFileValue(object.sourceIndex, path) }))),
      environment: window,
    });
    const apiWindow = window as typeof window & { FDOBench?: Record<string, unknown> };
    apiWindow.FDOBench = Object.freeze({ ...(apiWindow.FDOBench || {}), access, interoperabilitySimulation: interoperabilitySimulationHost });
  }, [drafts, activeObjects, activeObjectIds]);

  useEffect(() => {
    if (!interoperabilityStagesObject) return;
    const closeOnEscape = (event: globalThis.KeyboardEvent) => { if (event.key === "Escape") setInteroperabilityStagesObject(null); };
    document.addEventListener("keydown", closeOnEscape);
    return () => document.removeEventListener("keydown", closeOnEscape);
  }, [interoperabilityStagesObject]);

  const edit = (id: ObjectId, file: FileName, value: string) =>
    setDrafts((current) => ({ ...current, [draftKey(id, file)]: value }));
  const reset = (id: ObjectId, file: FileName) =>
    setDrafts((current) => Object.fromEntries(Object.entries(current).filter(([key]) => key !== draftKey(id, file))));
  const openMetadataInteraction = (id: ObjectId) => {
    const available = metadataFilesForObject(id);
    setLeftObject(id);
    setLeftFile((current) => available.some((file) => file === current) ? current : (available[0] ?? FILTERED_FILES[0]));
    setMetadataInteractObject(id);
  };

  return (
    <main>
      <div className="persistentHeader">
        <header className="topbar">
          <div className="brandCopy">
            <h1>FAIR Knowledge Object Bench</h1>
          </div>
          <div className="topActions">
            <button type="button" className="abstractButton" onClick={() => setAbstractOpen(true)}>Workshop Abstract</button>
          </div>
        </header>

        <div className="contextBar">
          <div className="contextBarLayout">
            <div className="contextDestinations contextDestinationsLeft" aria-label="Knowledge object controls">
              <button type="button" className={`filesReturnButton knowledgeObjectsControl ${workspaceView === "objects" ? "activeDestination" : ""}`} aria-pressed={workspaceView === "objects"} onClick={() => { setActiveExercise(null); setWorkspaceView("objects"); setKoPanelReset((value) => value + 1); }}>Knowledge Objects</button>
              <button
                type="button"
                className={`filesReturnButton ${workspaceView === "files" && !activeExercise ? "activeDestination" : ""}`}
                aria-pressed={workspaceView === "files" && !activeExercise}
                onClick={() => { setActiveExercise(null); setWorkspaceView("files"); setMetadataInteractObject(null); }}
              >Metadata Rig</button>
            </div>
            <div className="exerciseControlCluster">
            <div className="exerciseButtons" aria-label="Exercise controls">
              <button type="button" className={`knowledgeExerciseButton ${activeExercise === "K" ? "active" : ""}`} aria-label="K exercise" aria-pressed={activeExercise === "K"} onClick={() => { setWorkspaceView("files"); setActiveExercise("K"); }}>K</button>
              {(["F", "A", "I", "R"] as const).map((exercise) => (
                <button
                  type="button"
                  key={exercise}
                  className={activeExercise === exercise ? "active" : ""}
                  aria-label={`${exercise} exercise`}
                  aria-pressed={activeExercise === exercise}
                  onClick={() => {
                    setWorkspaceView("files");
                    setActiveExercise(exercise);
                  }}
                >{exercise}</button>
              ))}
            </div>
              <span className="contextLabel">Metadata Exercises</span>
            </div>
            <div className="contextDestinations" aria-label="Knowledge assembly controls">
              <button type="button" className={`filesReturnButton ${workspaceView === "assembly" ? "activeDestination" : ""}`} aria-pressed={workspaceView === "assembly"} disabled={!EMBEDDED_ASSEMBLY} onClick={() => { setActiveExercise(null); setWorkspaceView("assembly"); }}>Knowledge Assembly</button>
            </div>
          </div>
        </div>
      </div>

      {workspaceView === "objects" ? (
        <section className="knowledgeObjectsExercise" aria-label="Knowledge Objects explorer">
          <div className="viewStickyControls">
            <div className="viewTitle"><div className="koInstrumentMark">KOs</div><h2>Knowledge Objects</h2></div>
            <p>Explore contents and capabilities</p>
          </div>
          <div className="koGrid" key={koPanelReset}>{activeObjectIds.map((id) => <KnowledgeObjectShade key={id} objectId={id} drafts={drafts} />)}</div>
        </section>
      ) : workspaceView === "assembly" && EMBEDDED_ASSEMBLY ? (
        <KnowledgeAssemblyWorkspace assemblyLoaded={isAssemblyActive(activeObjects)} onLoad={() => setActiveObjects((current) => addAssemblyToActiveObjects(current, EMBEDDED_ASSEMBLY))} />
      ) : activeExercise === "K" ? (
        <section className="knowledgeExercise" aria-label="Knowledge exercise">
          <div className="viewStickyControls">
            <div className="viewTitle"><div className="searchInstrumentMark knowledgeInstrumentMark">K</div><h2>Knowledge</h2></div>
            <p>Distinguish computable knowledge from the evidence it is based on</p>
          </div>
          <div className="knowledgeGrid">{activeObjectIds.map((objectId) => {
            let model;
            let metadata: Record<string, unknown> | null = null;
            try { metadata = JSON.parse(workingFileValue(objectId, "metadata.json", drafts)); model = projectKnowledgeViewModel(buildKnowledgeViewModel(metadata), metadata, annotationDestinationOverrides[String(objectId)] ?? []); }
            catch { model = projectKnowledgeViewModel(buildKnowledgeViewModel(null), null); }
            const dependencyNames = Array.from(new Set<string>(model.linkedKnowledgeObjects.map((reference: { [key: string]: string }) => {
              const identifier = reference?.["@id"];
              const knownId = OBJECT_IDS.find((id) => {
                try { return JSON.parse(workingFileValue(id, "metadata.json", drafts))["@id"] === identifier; }
                catch { return false; }
              });
              return knownId ? objectName(knownId) : identifier || "Identifier not declared";
            })));
            const availableFacets = 2 + (model.dependencyCount !== null ? 1 : 0);
            const declaredFacets = Number(model.elements.length > 0) + Number(model.evidenceCount > 0) + Number(model.dependencyCount !== null && model.dependencyCount > 0);
            const nexus = evidenceNexusIndicator(model.linkingCategory.category);
            return <details className="accessibilityCard knowledgeCard" key={objectId} data-knowledge-elements={model.elements.length} data-evidential-sources={model.evidenceCount}>
              <summary><strong>{objectName(objectId)}</strong><span className="knowledgeTabIndicators"><button className="knowledgeOpenButton knowledgeTabExplore" type="button" aria-label={`Explore ${objectName(objectId)}`} onClick={(event) => { event.preventDefault(); event.stopPropagation(); setOpenKnowledgeSubgraph({ objectId, model, metadata }); }}>Explore</button><span className={`knowledgeNexusLabel nexusLevel${nexus.level}`} title={nexus.explanation} tabIndex={0} aria-label={`${nexus.label}: ${nexus.explanation}`}>{nexus.label}</span><span className={`knowledgeFacetCount ${declaredFacets === availableFacets ? "hasFacets" : "incompleteFacets"}`}>{declaredFacets} Facets</span></span></summary>
              <div className="facetList knowledgeCardBody">
                <section className="facetRow knowledgeFacetRow declared" aria-label="Knowledge Elements facet"><span className="facetNumber">1</span><div className="facetCopy"><div className="knowledgeFacetHeading"><strong>Knowledge Elements</strong><span>{model.elements.length} {model.elements.length === 1 ? "element" : "elements"}</span></div><small className="knowledgeFacetDescription">What this object computes and where it is implemented</small>
                  <div className="knowledgeFacetContent">{model.elements.length ? model.elements.map((element: { identifier: string; index: number; name: string; description: string; implementations: Array<{ path: string }> }) => <article className="knowledgeElementCard" key={`${element.identifier}-${element.index}`}><h3>{element.name}</h3><p>{knowledgePanelSummary(element.description)}</p><div className="knowledgeImplementation"><span>Implementation</span>{element.implementations.length ? <><code>{element.implementations[0].path}</code>{element.implementations.length > 1 && <span>+{element.implementations.length - 1} more</span>}</> : <span>Implementation path not declared</span>}</div></article>) : <p className="knowledgeEmptyState">No knowledge elements declared.</p>}</div>
                </div></section>
                <section className={`facetRow knowledgeFacetRow ${model.evidenceCount ? "declared" : "missing"}`} aria-label="Evidential Sources facet"><span className="facetNumber">2</span><div className="facetCopy"><div className="knowledgeFacetHeading"><strong>Evidential Sources</strong><span>{model.evidenceCount} {model.evidenceCount === 1 ? "source" : "sources"}</span></div><small className="knowledgeFacetDescription">Sources declared as a basis for this object&apos;s knowledge{model.dependencyCount !== null ? "; constituent KO evidence is not inherited" : ""}</small>
                  <div className="knowledgeFacetContent">{model.elements.filter((element: { evidentialBasis: unknown[] }) => element.evidentialBasis.length).map((element: { identifier: string; index: number; name: string; evidentialBasis: unknown[] }) => <section className="knowledgeEvidenceGroup knowledgeEvidenceMapRow" aria-label={`Evidence for ${element.name}`} key={`${element.identifier}-${element.index}`}><h3>Evidence for {element.name}</h3><span>{element.evidentialBasis.length} {element.evidentialBasis.length === 1 ? "source" : "sources"}</span></section>)}{model.koEvidentialBasis.length > 0 && <section className="knowledgeKoEvidence knowledgeEvidenceMapRow" aria-label="Evidence for this KO"><h3>Evidence for this KO</h3><span>{model.koEvidentialBasis.length} {model.koEvidentialBasis.length === 1 ? "source" : "sources"}</span></section>}{!model.evidenceCount && <p className="knowledgeEmptyState">No evidential basis declared anywhere in this KO.</p>}</div>
                </div></section>
                {model.dependencyCount !== null && <section className={`facetRow knowledgeFacetRow ${model.dependencyCount ? "declared" : "missing"}`} aria-label="KO Dependencies facet"><span className="facetNumber">3</span><div className="facetCopy"><div className="knowledgeFacetHeading"><strong>KO Dependencies</strong><span>{model.dependencyCount} {model.dependencyCount === 1 ? "KO" : "KOs"}</span></div><small className="knowledgeFacetDescription">Knowledge Objects incorporated by this assembly</small><div className="knowledgeFacetContent">{dependencyNames.length ? <ul className="knowledgeDependencyList">{dependencyNames.map((name: string) => <li key={name}>{name}</li>)}</ul> : <p className="knowledgeEmptyState">No KO dependencies declared.</p>}</div></div></section>}
              </div>
            </details>;
          })}</div>
        </section>
      ) : activeExercise === "F" ? (
        <section className="searchExercise" aria-label="Findability exercise">
          <div className="viewStickyControls">
            <div className="viewTitle"><div className="searchInstrumentMark">F</div><h2>Findability</h2></div>
            <p>Search knowledge object metadata</p>
            <div className="searchControls">
              <form className="searchForm" onSubmit={(event) => { event.preventDefault(); const query = searchQuery.trim(); setSubmittedSearchQuery(query); setSearchResults(query ? searchKnowledgeObjects(query, drafts, activeObjectIds) : null); }}>
                <span className="searchIcon" aria-hidden="true" />
                <input type="search" aria-label="Search knowledge objects" aria-keyshortcuts="Enter" enterKeyHint="search" autoFocus placeholder="Search knowledge objects" value={searchQuery} onChange={(event) => { const value = event.target.value; setSearchQuery(value); if (!value) { setSubmittedSearchQuery(""); setSearchResults(null); } }} />
                {searchQuery && <button type="button" className="clearSearchButton" aria-label="Clear search" onClick={() => { setSearchQuery(""); setSubmittedSearchQuery(""); setSearchResults(null); }}>×</button>}
                <button type="submit">Search</button>
              </form>
            </div>
          </div>
          <div className="searchResults" aria-live="polite">
              <div className="findabilityGrid">
                {activeObjectIds.map((objectId) => {
                  const objectResults = (searchResults ?? []).filter((result) => result.objectId === objectId);
                  const facets = findabilityFacets(objectId, drafts);
                  const declaredFacets = facets.filter((facet) => facet.values.length > 0).length;
                  return (
                  <details className={`resultGroup${declaredFacets ? "" : " zeroFacets"}`} key={objectId}>
                    <summary><strong>{objectName(objectId)}</strong><button type="button" className={`resultCount ${searchResults === null ? "matchIdle" : objectResults.length ? "matchPositive" : "matchZero"}`} disabled={searchResults === null || objectResults.length === 0} onClick={(event) => { event.preventDefault(); event.stopPropagation(); if (objectResults.length) setOpenFindabilityResults({ objectId, query: submittedSearchQuery, results: objectResults }); }}>{searchResults === null ? "Matches" : `${objectResults.length} ${objectResults.length === 1 ? "match" : "matches"}`}</button><button type="button" className="findabilityAuditButton" onClick={(event) => { event.preventDefault(); event.stopPropagation(); setOpenFindabilityAudit({ objectId, rows: runFindabilityAudit(objectId, drafts) }); }}>Audit</button><span className={`facetCount ${declaredFacets === facets.length ? "hasFacets" : "incompleteFacets"}`}>{declaredFacets} Facets</span></summary>
                    <div className="resultGroupBody">
                      <div className="findabilityFacetList">{facets.map((facet, index) => { const keyValue = ["Subjects", "Collection & indexing", "Technical characteristics"].includes(facet.name); return <div className={`findabilityFacetRow${facet.values.length ? " declared" : " missing"}${keyValue ? " keyValue" : ""}${facet.name === "Search terms" ? " searchTerms" : ""}`} key={facet.name}><span className="facetNumber">{index + 1}</span><span className="facetCopy"><strong className="facetLabel" tabIndex={0} data-question={facet.question} aria-label={`${facet.name}: ${facet.question}`}>{facet.name}</strong><FindabilityFacetContent facet={facet} /></span></div>; })}</div>
                    </div>
                  </details>
                  );
                })}
              </div>
          </div>
        </section>
      ) : activeExercise === "A" ? (() => {
        const card = (objectId: ObjectId) => {
          const links = accessibilityLinks(objectId, drafts);
          const copy = (link: AccessibilityPoint) => <span><span className="accessPointHeading"><strong>{link.label}</strong>{link.status && <span className={`accessTag ${link.status}`}>{link.status === "authentication" ? "Authentication required" : "Open"}</span>}</span><small>{link.host} · {link.display}</small></span>;
          return <details className={`accessibilityCard${links.length ? "" : " zeroLinks"}`} key={objectId}><summary><strong>{objectName(objectId)}</strong><span className={links.length ? "hasLinks" : undefined}>{links.length} {links.length === 1 ? "option" : "options"}</span></summary><div className="accessibilityCardBody">{links.length ? links.map((link, index) => link.kind === "web" ? <a className="accessPoint" href={link.href} target="_blank" rel="noopener noreferrer" key={`${link.kind}/${link.href}`}><span className="linkGlyph" aria-hidden="true">↗</span>{copy(link)}</a> : <button className="accessPoint" type="button" key={`${link.kind}/${link.knowledgeObjectId}/${index}`} onClick={async () => { setAccessErrors((current) => ({ ...current, [objectId]: undefined })); const result = await (window as typeof window & { FDOBench?: { access?: { downloadKnowledgeObject?: (options: Record<string, string>) => Promise<unknown> } } }).FDOBench?.access?.downloadKnowledgeObject?.({ knowledgeObjectId: link.knowledgeObjectId ?? objectName(objectId), content: "embedded", format: "zip" }) as { ok?: boolean; status?: string; message?: string } | undefined; if (result && !result.ok && result.status !== "authentication-cancelled") setAccessErrors((current) => ({ ...current, [objectId]: result.message ?? "The knowledge object could not be downloaded." })); }}><span className="linkGlyph" aria-hidden="true">↓</span>{copy(link)}</button>) : <div className="noLinks">No declared access points found.</div>}{accessErrors[objectId] ? <p className="accessDownloadError" role="alert">{accessErrors[objectId]}</p> : null}</div></details>;
        };
        return (
        <section className="accessibilityExercise" aria-label="Accessibility exercise">
          <div className="viewStickyControls"><div className="viewTitle"><div className="searchInstrumentMark">A</div><h2>Access</h2></div><p>Get knowledge objects using declared access methods</p></div>
          <div className="accessibilityGrid">{activeObjectIds.map(card)}</div>
        </section>
        );
      })() : activeExercise === "I" ? (() => {
        const stateFor = (state: number): ExerciseFacetState => ({ semantics: state >= 1 ? "complete" : "missing", profiles: state >= 2 ? "complete" : "missing", interface: state >= 3 ? "complete" : "missing" });
        const simulationFor = (kit: InteroperabilityExerciseKit, state: number) => { if (!kit.execution) return null; const contract = state === 3, profiled = state >= 2; return interoperabilitySimulationHost.simulate({ target: kit.target, mode: contract ? "contract" : "raw", input: profiled ? kit.execution.contractInput : kit.execution.rawInput, expectedOutput: profiled ? kit.execution.contractOutput : kit.execution.rawOutput, manifest: contract ? kit.execution.contractManifest : kit.execution.rawManifest }) as SimulationResult; };
        const openStages = (objectId: ObjectId, kit: InteroperabilityExerciseKit) => { const session = { state: stateFor(0), selectedState: 0, repairs: [], executionResult: simulationFor(kit, 0), resetVersion: 0 }; setInteroperabilitySessions((current) => ({ ...current, [objectId]: session })); setInteroperabilityStagesObject(objectId); };
        const chooseStage = (objectId: ObjectId, kit: InteroperabilityExerciseKit, state: number) => setInteroperabilitySessions((current) => ({ ...current, [objectId]: { ...(current[objectId] ?? { resetVersion: 0 }), state: stateFor(state), selectedState: state, repairs: [], executionResult: simulationFor(kit, state) } as InteroperabilitySimulationSession }));
        const panel = (objectId: ObjectId) => {
          const published = publishedInteroperabilityModel(objectId, drafts);
          const exerciseDiscovery = interoperabilityExerciseDiscovery(objectId, drafts);
          const kit = exerciseDiscovery.status === "available" ? exerciseDiscovery.kit : null;
          const declaredFacets = published.boundary.questions.filter((question) => question.answered).length;
          return <details className={`accessibilityCard interoperabilityPanel${declaredFacets ? "" : " zeroFacets"}`} key={objectId}><summary><strong>{objectName(objectId)}</strong><button type="button" className="interoperabilityStagesButton" disabled={!kit} title={kit ? "Explore interoperability stages" : "Stages are not supplied for this knowledge object"} onClick={(event) => { event.preventDefault(); event.stopPropagation(); if (kit) openStages(objectId, kit); }}>Stages</button><span className={declaredFacets === 3 ? "hasFacets" : "incompleteFacets"}>{declaredFacets} Facets</span></summary>{exerciseDiscovery.status === "invalid" && <div className="educationalFallback" role="status"><strong>Educational component unavailable</strong><span>{exerciseDiscovery.message}</span><small>Published KO metadata remains available.</small></div>}<InteroperabilityBoundaryPanel published={published} exerciseKit={null} session={null} onRepair={() => undefined} onExecutionResult={() => undefined} />{!published.facets.length && <pre className="interoperabilityRaw">{published.raw || "No interoperability metadata declared."}</pre>}</details>;
        };
        const stageObject = interoperabilityStagesObject;
        const stageDiscovery = stageObject ? interoperabilityExerciseDiscovery(stageObject, drafts) : null;
        const stageKit = stageDiscovery?.status === "available" ? stageDiscovery.kit : null;
        const stageSession = stageObject ? interoperabilitySessions[stageObject] ?? null : null;
        return (<>
          <section className="interoperabilityExercise" aria-label="Interoperability exercise">
            <div className="viewStickyControls"><div className="viewTitle"><div className="searchInstrumentMark">I</div><h2>Interoperability</h2></div><p>See how metadata bring greater interoperability</p></div>
            <div className="interoperabilityGrid">{activeObjectIds.map(panel)}</div>
          </section>
          {stageObject && stageKit && stageSession && createPortal(<div className="interoperabilityStagesBackdrop" role="dialog" aria-modal="true" aria-labelledby="interoperability-stages-title"><section className="interoperabilityStagesDialog"><header><div><span>Interoperability stages</span><h2 id="interoperability-stages-title">{objectName(stageObject)}</h2></div><button type="button" className="modalClose" autoFocus aria-label="Close interoperability stages" onClick={() => setInteroperabilityStagesObject(null)}>×</button></header><div className="interoperabilityStagesToolbar"><div className="stateSelector modeStateSelector" role="group" aria-label="Choose interoperability simulation stage">{["Opaque", "Meaning", "Data Objects", "Interface"].map((label, state) => <button type="button" key={label} className={stageSession.selectedState === state ? "active" : ""} aria-pressed={stageSession.selectedState === state} onClick={() => chooseStage(stageObject, stageKit, state)}><span>{label}</span></button>)}</div></div><div className="interoperabilityStagesBody"><InteroperabilityBoundaryPanel published={publishedInteroperabilityModel(stageObject, drafts)} exerciseKit={stageKit} session={stageSession} onRepair={() => undefined} onExecutionResult={(state) => chooseStage(stageObject, stageKit, state)} /></div></section></div>, document.body)}
        </>);
      })() : activeExercise === "R" ? (() => {
        const card = (objectId: ObjectId) => {
          const facets = reusabilityFacets(objectId, drafts);
          const declared = facets.filter((facet) => facet.value).length;
          return <details className={`accessibilityCard reusabilityCard${declared ? "" : " zeroFacets"}`} key={objectId}><summary><strong>{objectName(objectId)}</strong><span className={declared === facets.length ? "hasFacets" : "incompleteFacets"}>{declared} Facets</span></summary><div className="facetList">{facets.map((facet, index) => <div className={`facetRow ${facet.value ? "declared" : "missing"}`} key={facet.name}><span className="facetNumber">{index + 1}</span><span className="facetCopy"><strong className="facetLabel" tabIndex={0} data-question={facet.question} aria-label={`${facet.name}: ${facet.question}`}>{facet.name}</strong>{facet.scope ? <ScopeFacetProjection scope={facet.scope} /> : facet.provenance ? <ProvenanceFacetProjection provenance={facet.provenance} /> : facet.tests?.length ? <TestsFacetProjection tests={facet.tests} onOpen={(test) => { if (test.sourcePath) setOpenTest({ objectId, file: test.sourcePath }); }} /> : facet.evidence?.length ? <EvidenceFacetProjection evidence={facet.evidence} onOpen={(item) => { if (item.sourcePath) setOpenEvidence({ objectId, file: item.sourcePath }); }} /> : facet.href ? <a className={facet.property === "schema:license" ? "licenseResourceLink" : undefined} href={facet.href} target="_blank" rel="noopener noreferrer">{facet.value}{facet.property === "schema:license" ? <span aria-hidden="true">↗</span> : null}</a> : <small>{facet.value || "Not declared"}</small>}</span></div>)}</div></details>;
        };
        return (
        <section className="reusabilityExercise" aria-label="Reusability exercise">
          <div className="viewStickyControls"><div className="viewTitle"><div className="searchInstrumentMark">R</div><h2>Reusability</h2></div><p>See how metadata support reusability</p></div>
          <div className="reusabilityGrid">{activeObjectIds.map(card)}</div>
        </section>
        );
      })() : <section className="metadataRigExercise" aria-label="Metadata rig">
        <div className="viewStickyControls">
          <div className="viewTitle"><div className="searchInstrumentMark metadataInstrumentMark">M</div><h2>Metadata</h2></div>
          <p>A rig to interact with Knowledge Object metadata</p>
        </div>
        <div className="metadataRigGrid">{activeObjectIds.map((objectId) => {
          const available = metadataFilesForObject(objectId);
          const completed = completedMetadataFilesForObject(objectId, drafts);
          return <details className={`metadataRigCard${available.length ? "" : " noMetadataFiles"}`} key={objectId}>
            <summary><strong>{objectName(objectId)}</strong><button type="button" className="metadataInteractButton" onClick={(event) => { event.preventDefault(); event.stopPropagation(); openMetadataInteraction(objectId); }}>Interact</button><span className={completed.length === available.length ? "hasFiles" : "incompleteFiles"}>{completed.length} Files</span></summary>
            <div className="metadataRigInventory">{FILTERED_FILES.map((fileName, index) => { const present = available.includes(fileName), complete = completed.includes(fileName); return <div className={present && complete ? "available" : "missing"} key={fileName}><span>{index + 1}</span><strong>{METADATA_RECORD_LABELS[fileName]}</strong><small>{complete ? "Completed" : present ? "Incomplete" : "Not available"}</small></div>; })}</div>
          </details>;
        })}</div>
      </section>}

      <footer className="appFooter">
        <span>Instrument set: {activeObjectIds.length} embedded knowledge {activeObjectIds.length === 1 ? "object" : "objects"}</span>
        <span className="footerDivider" />
        <span>Edits remain on this device</span>
        <span className="footerDivider" />
        <nav className="footerRepositories" aria-label="Source repositories">
          <a href="https://github.com/kgrid/ko-metadata-bench" target="_blank" rel="noopener noreferrer">Workbench repository</a>
          <a href="https://github.com/kgrid-objects/FAIR-DO-Workshop" target="_blank" rel="noopener noreferrer">KO and KA repository</a>
        </nav>
      </footer>
      {abstractOpen && <AbstractDialog onClose={() => setAbstractOpen(false)} />}
      {openTest && <EmbeddedTestDialog objectId={openTest.objectId} file={openTest.file} source={workingFileValue(openTest.objectId, openTest.file, drafts)} onClose={() => setOpenTest(null)} />}
      {openEvidence && <EmbeddedEvidenceDialog objectId={openEvidence.objectId} file={openEvidence.file} onClose={() => setOpenEvidence(null)} />}
      {openKnowledgeSubgraph && createPortal(<KnowledgeSubgraphDialog objectId={openKnowledgeSubgraph.objectId} model={openKnowledgeSubgraph.model} metadata={openKnowledgeSubgraph.metadata} onClose={() => setOpenKnowledgeSubgraph(null)} />, document.body)}
      {openFindabilityResults && <FindabilityResultsDialog objectId={openFindabilityResults.objectId} query={openFindabilityResults.query} results={openFindabilityResults.results} onClose={() => setOpenFindabilityResults(null)} />}
      {openFindabilityAudit && <FindabilityAuditDialog objectId={openFindabilityAudit.objectId} rows={openFindabilityAudit.rows} onClose={() => setOpenFindabilityAudit(null)} />}
      {metadataInteractObject && createPortal(<div className="metadataInteractBackdrop" role="presentation"><section className="metadataInteractDialog" role="dialog" aria-modal="true" aria-labelledby="metadata-interact-title"><header><div><span>Metadata interaction</span><h2 id="metadata-interact-title">{objectName(metadataInteractObject)}</h2></div><button type="button" onClick={() => setMetadataInteractObject(null)} aria-label="Close metadata interaction">×</button></header><div className="workspaces singleEditorWorkspace metadataInteractWorkspace"><MetadataInteractionErrorBoundary key={`${metadataInteractObject}:${leftFile}`} objectId={metadataInteractObject} file={leftFile} onFileChange={setLeftFile}><WorkspacePane key={`${metadataInteractObject}-${leftFile}`} side="Metadata" objectId={metadataInteractObject} otherObjectId={0} file={leftFile} drafts={drafts} showObjectSelector={false} onObjectChange={() => {}} onFileChange={setLeftFile} onEdit={(value) => edit(metadataInteractObject, leftFile, value)} onReset={() => reset(metadataInteractObject, leftFile)} /></MetadataInteractionErrorBoundary></div></section></div>, document.body)}
    </main>
  );
}
